sys_script_include.script:
var SVPDPUtils = Class.create();
SVPDPUtils.prototype = {
	HOME_PAGE: "homepage",
	KB_HOME_PAGE: "kb_knowledge_page",
	SC_HOME_PAGE: "sc_catalog_page",

	initialize: function () {
	},

	menuItemCondition: function (menuItemID) {
		var gr = new GlideRecord('sp_rectangle_menu_item');
		gr.get(menuItemID);

		if (gr.sp_rectangle_menu.toString() == 'f20072fc97f30f14d3efb73de053afb7') {
			if (gr.type == 'page') {
				return $sp.canSeePage(gr.sp_page.id + '') && gs.isLoggedIn();
			} else if (gr.type == 'sc' || gr.type == 'kb') {
				var homepage = this[gr.type.toUpperCase() + "_HOME_PAGE"];
				var pageID = $sp.getDisplayValue(homepage);
				return $sp.canSeePage(pageID) && (gr.type == "kb" ? true : gs.isLoggedIn());
			} else {
				gs.info("SVPDPUtils Info: Need to create condition in this Script Include for menu item " + menuItemID + ".");
				return false;
			}
		}

		if (gr.sp_rectangle_menu_item.toString() == 'aead52e797cc1b90d3efb73de053afe6') {
			if (gr.type == 'page') {
				var currentPage = $sp.getParameter('id');
				currentPage ? currentPage += '' : currentPage = '';

				//cross-check page route maps
				if (currentPage != '') {
					var prm = new GlideRecord('sp_page_route_map');
					prm.addQuery('portals', $sp.getPortalRecord().sys_id);
					prm.addQuery('route_from_page.id', currentPage);
					prm.query();

					if (prm.next()) {
						currentPage = prm.route_to_page.getDisplayValue();
					}
				}

				if (currentPage == '' && gr.sp_page.id + '' == $sp.getDisplayValue(this.HOME_PAGE) + '') {
					return false;
				} else {
					return $sp.canSeePage(gr.sp_page.id + '') && currentPage != gr.sp_page.id + '';
				}
			}
		}
	},

	menuItemURL: function (menuItemID) {
		//Populate with any URLs that would be better constructed using dynamic arguments rather than a specific string on the menu item itself
	},

	type: 'SVPDPUtils'
};
